  const s = str(v).toLowerCase().replace(/,/g, ' ').replace(/([0-9])(st|nd|rd|th)/g, '$1').replace(/ +/g, ' ').trim();
  if (!s) return null;
  if (s === 'today' || s === 'now' || s === 'asap' || s.indexOf('this morning') === 0 || s.indexOf('this afternoon') === 0) return now.startOf('day');
  if (s.indexOf('tomorrow') === 0) return now.plus({ days: 1 }).startOf('day');
  let d = DateTime.fromISO(s.slice(0, 10), { zone: tz });
  if (s.length >= 10 && d.isValid) return d.startOf('day');
  const fmts = ['M/d/yyyy', 'M/d/yy', 'M/d', 'MMMM d yyyy', 'MMMM d', 'MMM d yyyy', 'MMM d', 'EEEE MMMM d', 'EEEE MMM d'];
  for (const f of fmts) {
    d = DateTime.fromFormat(s, f, { zone: tz, locale: 'en-US' });
    if (d.isValid) {
      if (f.indexOf('y') === -1 && d < now.startOf('day')) d = d.plus({ years: 1 });
      return d.startOf('day');
    }
  }
  const wd = dayNames.findIndex(function (x) { return s.indexOf(x) !== -1; });
  if (wd >= 0) {
    let diff = (wd + 1) - now.weekday;
    if (diff < 0) diff += 7;
    if (diff === 0 && s.indexOf('next') !== -1) diff = 7;
    return now.plus({ days: diff }).startOf('day');
  }
  return 'invalid';
};
const parseTime = function (v) {
  let s = str(v).toLowerCase().replace(/[.]/g, '').replace(/ +/g, ' ').trim();
  if (!s) return '';
  if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}t/.test(s)) s = s.slice(11);
  if (s.indexOf('noon') !== -1) return '12:00';
  const m = s.match(/([0-9]{1,2})(?::([0-9]{2}))? ?(am|pm)?/);
  if (!m) return '';
  let h = parseInt(m[1], 10);
  const mi = m[2] ? parseInt(m[2], 10) : 0;
  const ap = m[3] || '';
  if (ap === 'pm' && h < 12) h += 12;
  if (ap === 'am' && h === 12) h = 0;
  if (!ap && h >= 1 && h <= 6) h += 12;
  if (h > 23 || mi > 59) return '';
  return String(h).padStart(2, '0') + ':' + String(mi).padStart(2, '0');
};
const daypartOf = function (t) {
  if (!t) return '';
  if (t.indexOf('morning') !== -1) return 'morning';
  if (t.indexOf('afternoon') !== -1 || t.indexOf('evening') !== -1) return 'afternoon';
  if (t.indexOf('first') !== -1 || t.indexOf('earliest') !== -1 || t.indexOf('any') !== -1 || t.indexOf('soon') !== -1) return 'any';
  return '';
};
const phoneDigits = function (v) { let d = str(v).replace(/[^0-9]/g, ''); if (d.length === 11 && d.charAt(0) === '1') d = d.slice(1); return d; };
const aliases = { info: 'get_info', faq: 'get_info', availability: 'check_availability', book: 'book_visit', book_site_visit: 'book_visit', schedule_visit: 'book_visit', book_appointment: 'book_visit', find: 'find_visit', find_appointment: 'find_visit', lookup_visit: 'find_visit', reschedule: 'reschedule_visit', reschedule_appointment: 'reschedule_visit', cancel: 'cancel_visit', cancel_appointment: 'cancel_visit', project_status: 'get_project_status', status: 'get_project_status', emergency: 'report_urgent', report_emergency: 'report_urgent', urgent: 'report_urgent', lead: 'capture_lead', call_summary: 'log_call', take_message: 'log_call' };
const groups = { get_info: 'info', check_availability: 'schedule', book_visit: 'schedule', find_visit: 'schedule', reschedule_visit: 'schedule', cancel_visit: 'schedule', get_project_status: 'project', report_urgent: 'ticket', capture_lead: 'ticket', log_call: 'ticket' };
const o = {};
let action = pick(['action', 'tool', 'intent']).toLowerCase().replace(/[ -]+/g, '_');
if (aliases[action]) action = aliases[action];
o.action = action;
o.group = groups[action] || 'unknown';
o.topic = pick(['topic', 'question', 'query']);
o.name = pick(['name', 'customer_name', 'caller_name']);
o.phone_raw = pick(['phone', 'phone_number', 'caller_phone', 'callback_number']);
o.phone = phoneDigits(o.phone_raw);
o.address = pick(['address', 'site_address', 'project_address', 'location']);
o.email = pick(['email']).toLowerCase().replace(/ +/g, '');
o.notes = pick(['notes', 'issue', 'problem', 'description']);
o.visit_id = pick(['visit_id', 'appointment_id', 'confirmation', 'confirmation_number']);
o.project_id = pick(['project_id', 'project_number', 'job_number']);
o.project_type = pick(['project_type', 'project', 'job_type']);
const vtRaw = pick(['visit_type', 'appointment_type', 'service_type']).toLowerCase();
o.visit_type = '';
if (vtRaw) {
  if (/warrant|punch|repair|fix|callback|touch/.test(vtRaw)) o.visit_type = 'warranty';
  else if (/walk|progress|existing|current|meeting/.test(vtRaw)) o.visit_type = 'walkthrough';
  else o.visit_type = 'estimate';
}
o.urgent_type = pick(['urgent_type', 'emergency_type', 'emergency']);
o.summary = pick(['summary', 'call_summary']);
o.outcome = pick(['outcome', 'result']);
o.details = pick(['details', 'project_details']);
o.budget = pick(['budget', 'budget_range']);
o.timeframe = pick(['timeframe', 'timeline']);
o.property_type = pick(['property_type']);
o.caller_type = pick(['caller_type']);
const setDate = function (v, prefix) {
  const d = parseDate(v);
  if (d === null) { o[prefix + 'date'] = ''; o[prefix + 'date_status'] = 'missing'; return; }
  if (d === 'invalid') { o[prefix + 'date'] = ''; o[prefix + 'date_status'] = 'invalid'; return; }
  o[prefix + 'date'] = d.toISODate(); o[prefix + 'date_spoken'] = d.toFormat('cccc, LLLL d'); o[prefix + 'date_status'] = 'ok';
};
setDate(pick(['date', 'visit_date', 'day']), '');
setDate(pick(['new_date']), 'new_');
const setTime = function (v, prefix) {
  const t = str(v).toLowerCase();
  const dp = daypartOf(t);
  o[prefix + 'daypart'] = dp;
  o[prefix + 'time'] = dp ? '' : parseTime(t);
};
setTime(pick(['window', 'arrival_window', 'time', 'preferred_time']), '');
setTime(pick(['new_window', 'new_time']), 'new_');
o.today = now.toISODate();
o.today_spoken = now.toFormat('cccc, LLLL d');
o.now_time = now.toFormat('HH:mm');
if (o.group === 'unknown') o.response = { success: false, message: 'Unknown action. Use get_info, check_availability, book_visit, find_visit, reschedule_visit, cancel_visit, get_project_status, report_urgent, capture_lead, or log_call.' };
return [{ json: o }];

const r = $('Normalize Request').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (x) { return x && x.topic; });
const reply = function (resp) { return [{ json: { response: resp } }]; };
const q = (r.topic || '').toLowerCase();
const topics = rows.map(function (x) { return x.topic; });
if (!q) {
  const about = rows.find(function (x) { return x.topic === 'about'; });
  return reply({ success: true, topics: topics, message: (about ? about.answer + ' ' : '') + 'I can help with pricing ranges, timelines, permits, financing, warranties, and scheduling a free estimate.' });
}
const stop = ['the', 'and', 'you', 'your', 'how', 'much', 'what', 'does', 'for', 'are', 'can', 'have', 'with', 'that', 'this', 'there', 'any', 'get', 'need', 'want', 'about', 'guys', 'offer', 'take', 'will', 'would'];
const ws = q.replace(/[^a-z0-9 ]/g, ' ').split(' ').filter(function (w) { return w.length > 2 && stop.indexOf(w) === -1; });
const scored = rows.map(function (x) {
  const hay = (x.topic.replace(/_/g, ' ') + ' ' + x.keywords).toLowerCase().split(' ');
  let s = x.topic === q.trim().replace(/ +/g, '_') ? 10 : 0;
  ws.forEach(function (w) { if (hay.some(function (k) { return k === w || (w.length > 3 && k.indexOf(w) === 0) || (k.length > 3 && w.indexOf(k) === 0); })) s += 1; });
  return { x: x, s: s };
}).filter(function (o) { return o.s > 0; }).sort(function (a, b) { return b.s - a.s; });
if (!scored.length) return reply({ success: false, topics: topics, message: 'I do not have that detail on hand. I can take a message and have the office call you back.' });
const best = scored.filter(function (o, i) { return i === 0 || (i === 1 && o.s === scored[0].s); });
return reply({ success: true, topic: best[0].x.topic, message: best.map(function (o) { return o.x.answer; }).join(' ') });

const r = $('Normalize Request').first().json;
const out = function (resp, extra) { const o = { response: resp, op: 'none' }; if (extra) { Object.keys(extra).forEach(function (k) { o[k] = extra[k]; }); } return [{ json: o }]; };
const sp = function (t) { const p = String(t).split(':'); let h = parseInt(p[0], 10); const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12; if (h === 0) h = 12; return h + (p[1] === '00' ? '' : ':' + p[1]) + ' ' + ap; };
const toMin = function (t) { const p = String(t).split(':'); return parseInt(p[0], 10) * 60 + parseInt(p[1], 10); };
const joinOr = function (a) { if (a.length <= 1) return a.join(''); return a.slice(0, -1).join(', ') + (a.length > 2 ? ',' : '') + ' or ' + a[a.length - 1]; };
const spokenDate = function (iso) { return DateTime.fromISO(iso).toFormat('cccc, LLLL d'); };
const rowsOf = function (items, key) { return items.map(function (i) { return i.json; }).filter(function (x) { return x && x[key] !== undefined && x[key] !== null && x[key] !== ''; }); };
const label = function (w) { return sp(w.window_start) + ' to ' + sp(w.window_end); };
const clean = function (s) { return String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); };
const typeLabel = function (t) { if (t === 'warranty') return 'warranty visit'; if (t === 'walkthrough') return 'project walkthrough'; return 'free estimate visit'; };
const windows = rowsOf($('Get Schedule Windows').all(), 'window_start');
const visits = rowsOf($input.all(), 'visit_id');
const nowMin = toMin(r.now_time);
const maxDate = DateTime.fromISO(r.today).plus({ days: 45 }).toISODate();
const dayWindows = function (dateIso, excludeId) {
  const wd = DateTime.fromISO(dateIso).weekday;
  return windows.filter(function (w) { return Number(w.day_index) === wd; }).sort(function (a, b) { return toMin(a.window_start) - toMin(b.window_start); }).map(function (w) {
    const booked = visits.filter(function (a) { return a.status === 'confirmed' && a.visit_date === dateIso && a.window_start === w.window_start && a.id !== excludeId; }).length;
    const past = dateIso === r.today && toMin(w.window_start) < nowMin + 120;
    const left = Number(w.capacity) - booked;
    return { window_start: w.window_start, window_end: w.window_end, left: left, open: !past && left > 0 };
  });
};
const openOn = function (dateIso, excludeId) { return dayWindows(dateIso, excludeId).filter(function (w) { return w.open; }); };
const nextOpenings = function (fromIso, maxDays, excludeId) {
  const res = [];
  for (let i = 0; i < 10 && res.length < maxDays; i++) {
    const d = DateTime.fromISO(fromIso).plus({ days: i }).toISODate();
    if (d < r.today || d > maxDate) continue;
    const o = openOn(d, excludeId);
    if (o.length) res.push({ date: d, spoken: spokenDate(d), windows: o.map(label) });
  }
  return res;
};
const openingsText = function (list) { return list.map(function (x) { return x.spoken + ', ' + joinOr(x.windows); }).join('; '); };
const dateIssue = function (iso, status) {
  if (status === 'invalid') return "Sorry, I didn't catch the date. Could you say it like this Friday, or November 20th?";
  if (!iso) return 'What day works best for you?';
  if (iso < r.today) return 'That date has already passed. What upcoming day works for you?';
  if (iso > maxDate) return 'We schedule site visits up to 45 days out. Is there an earlier day that works?';
  return '';
};
const pickWindow = function (open, time, daypart) {
  if (time) { const t = toMin(time); return open.find(function (w) { return t >= toMin(w.window_start) && t < toMin(w.window_end); }) || null; }
  if (daypart === 'morning') return open.find(function (w) { return toMin(w.window_start) < 720; }) || null;
  if (daypart === 'afternoon') return open.find(function (w) { return toMin(w.window_start) >= 720; }) || null;
  if (daypart === 'any') return open[0] || null;
  return null;
};
const resolveSlot = function (dateIso, time, daypart, excludeId) {
  const all = dayWindows(dateIso, excludeId);
  const open = all.filter(function (w) { return w.open; });
  const ds = spokenDate(dateIso);
  const after = DateTime.fromISO(dateIso).plus({ days: 1 }).toISODate();
  if (!all.length) { const nx = nextOpenings(after, 2, excludeId); return { ok: false, need: 'date', open: [], message: 'We do not schedule site visits on ' + DateTime.fromISO(dateIso).toFormat('cccc') + 's.' + (nx.length ? ' The next openings are ' + openingsText(nx) + '.' : '') }; }
  if (!open.length) { const nx2 = nextOpenings(after, 2, excludeId); return { ok: false, need: 'date', open: [], message: 'We have no openings left on ' + ds + '.' + (nx2.length ? ' The next openings are ' + openingsText(nx2) + '.' : '') }; }
  if (!time && !daypart) return { ok: false, need: 'window', open: open, message: 'On ' + ds + ' we have arrival windows of ' + joinOr(open.map(label)) + '. Which works best?' };
  const w = pickWindow(open, time, daypart);
  if (w) return { ok: true, window: w };
  return { ok: false, need: 'window', open: open, message: 'That time is not available on ' + ds + '. I can offer ' + joinOr(open.map(label)) + '. Would one of those work?' };
};
const describe = function (a) { return typeLabel(a.visit_type) + ' on ' + spokenDate(a.visit_date) + ' between ' + sp(a.window_start) + ' and ' + sp(a.window_end); };
const upcomingFor = function () { return visits.filter(function (a) { return a.status === 'confirmed' && a.phone === r.phone && a.visit_date >= r.today; }).sort(function (a, b) { return (a.visit_date + a.window_start) < (b.visit_date + b.window_start) ? -1 : 1; }); };
const pickTarget = function () {
  if (r.phone.length !== 10) return { need: 'phone', message: 'What phone number is the site visit under?' };
  const up = upcomingFor();
  if (!up.length) return { need: 'not_found', message: "I don't see an upcoming site visit under that phone number. Could it be under a different number?" };
  if (r.visit_id) { const t = up.find(function (a) { return clean(a.visit_id) === clean(r.visit_id); }); if (t) return { target: t }; }
  if (up.length === 1) return { target: up[0] };
  return { need: 'which', message: 'I see ' + up.length + ' upcoming visits: ' + up.map(function (a) { return a.visit_id + ', a ' + describe(a); }).join('; ') + '. Which one do you mean?' };
};

if (r.action === 'check_availability') {
  if (r.date_status === 'missing') {
    const nx = nextOpenings(r.today, 3, null);
    return out({ success: true, openings: nx, message: nx.length ? 'Our next openings are ' + openingsText(nx) + '. What works best for you?' : 'I do not see any openings in the next week. I can take your details and have the office call you.' });
  }
  const di = dateIssue(r.date, r.date_status);
  if (di) return out({ success: false, need: 'date', message: di });
  const s = resolveSlot(r.date, r.time, r.daypart, null);
  if (s.ok) return out({ success: true, available: true, date: r.date, window_start: s.window.window_start, window_end: s.window.window_end, message: 'Yes, we have ' + label(s.window) + ' open on ' + r.date_spoken + '. Would you like me to book it?' });
  return out({ success: s.need === 'window', available: false, date: r.date, open_windows: s.open.map(label), message: s.message });
}

if (r.action === 'book_visit') {
  const vt = r.visit_type || 'estimate';
  if (vt === 'estimate' && /custom home|new home|new house|new build|ground up|commercial|build.?out|tenant/.test(r.project_type.toLowerCase())) return out({ success: false, need: 'use_capture_lead', message: 'Custom homes and commercial projects start with a call from a project consultant. Collect the caller details and use capture_lead instead.' });
  const di = dateIssue(r.date, r.date_status);
  if (di) return out({ success: false, need: 'date', message: di });
  const s = resolveSlot(r.date, r.time, r.daypart, null);
  if (!s.ok) return out({ success: false, need: s.need, open_windows: s.open.map(label), message: s.message });
  if (!r.name) return out({ success: false, need: 'name', message: 'What name should I put the visit under?' });
  if (r.phone.length !== 10) return out({ success: false, need: 'phone', message: 'What is the best phone number to reach you, area code first?' });
  if (!r.address) return out({ success: false, need: 'address', message: 'What is the address of the property?' });
  if (vt === 'estimate' && !r.project_type) return out({ success: false, need: 'project_type', message: 'What kind of project is this for?' });
  if (vt !== 'estimate' && !r.notes) return out({ success: false, need: 'notes', message: 'Can you briefly describe what you would like us to look at?' });
  const dup = visits.find(function (a) { return a.status === 'confirmed' && a.phone === r.phone && a.visit_date === r.date; });
  if (dup) return out({ success: false, existing_visit_id: dup.visit_id, message: 'You already have a ' + describe(dup) + ', confirmation ' + dup.visit_id + '. Would you like to change that one instead?' });
  const id = 'MR-' + Math.floor(2000 + Math.random() * 8000);
  const first = r.name.split(' ')[0];
  const who = vt === 'estimate' ? 'An estimator' : (vt === 'walkthrough' ? 'Your project manager' : 'A project manager');
  const row = { visit_id: id, customer_name: r.name, phone: r.phone, address: r.address, visit_type: vt, project_type: r.project_type || '', notes: r.notes || r.details || '', visit_date: r.date, window_start: s.window.window_start, window_end: s.window.window_end, status: 'confirmed', source: 'voice agent' };
  return out({ success: true, visit_id: id, visit_type: vt, date: r.date, window_start: row.window_start, window_end: row.window_end, message: "You're all set, " + first + '. ' + who + ' will arrive on ' + r.date_spoken + ' between ' + sp(row.window_start) + ' and ' + sp(row.window_end) + '. Your confirmation number is ' + id + '. You will get a text about 30 minutes before arrival.' }, { op: 'insert', row: row });
}

if (r.action === 'find_visit') {
  if (r.phone.length !== 10) return out({ success: false, need: 'phone', message: 'What phone number is the site visit under?' });
  const up = upcomingFor();
  if (!up.length) return out({ success: false, found: false, message: "I don't see an upcoming site visit under that phone number. Could it be under a different number?" });
  return out({ success: true, found: true, visits: up.map(function (a) { return { visit_id: a.visit_id, customer_name: a.customer_name, visit_type: a.visit_type, project_type: a.project_type, date: a.visit_date, window_start: a.window_start, window_end: a.window_end, address: a.address }; }), message: 'I found ' + (up.length > 1 ? up.length + ' visits: a ' : 'a ') + up.map(function (a) { return describe(a) + ' under ' + a.customer_name + ', confirmation ' + a.visit_id; }).join('; and a ') + '.' });
}

if (r.action === 'reschedule_visit') {
  const p = pickTarget();
  if (!p.target) return out({ success: false, need: p.need, message: p.message });
  const t = p.target;
  const dStatus = r.new_date_status !== 'missing' ? r.new_date_status : r.date_status;
  const dIso = r.new_date_status !== 'missing' ? r.new_date : r.date;
  const time = r.new_time || r.time;
  const daypart = r.new_daypart || r.daypart;
  if (dStatus === 'missing' && !time && !daypart) return out({ success: false, need: 'change', visit_id: t.visit_id, message: 'I found your ' + describe(t) + '. What day and time would you like instead?' });
  const eff = dStatus === 'missing' ? t.visit_date : dIso;
  const di = dateIssue(eff, dStatus === 'missing' ? 'ok' : dStatus);
  if (di) return out({ success: false, need: 'date', message: di });
  const s = resolveSlot(eff, time, daypart, t.id);
  if (!s.ok) return out({ success: false, need: s.need, open_windows: s.open.map(label), message: s.message });
  if (eff === t.visit_date && s.window.window_start === t.window_start) return out({ success: false, need: 'change', message: 'That is the window you already have. What other day or time would you like?' });
  return out({ success: true, visit_id: t.visit_id, date: eff, window_start: s.window.window_start, window_end: s.window.window_end, message: 'Done. Your visit is now on ' + spokenDate(eff) + ' between ' + sp(s.window.window_start) + ' and ' + sp(s.window.window_end) + '. Your confirmation number stays ' + t.visit_id + '.' }, { op: 'update', row_id: t.id, update: { visit_date: eff, window_start: s.window.window_start, window_end: s.window.window_end, status: 'confirmed' } });
}

if (r.action === 'cancel_visit') {
  const p = pickTarget();
  if (!p.target) return out({ success: false, need: p.need, message: p.message });
  const t = p.target;
  return out({ success: true, visit_id: t.visit_id, message: 'Your ' + describe(t) + ' is cancelled. There is no charge. Call us any time to rebook.' }, { op: 'update', row_id: t.id, update: { visit_date: t.visit_date, window_start: t.window_start, window_end: t.window_end, status: 'cancelled' } });
}

return out({ success: false, message: 'Unsupported scheduling action.' });

const r = $('Normalize Request').first().json;
const rows = $input.all().map(function (i) { return i.json; }).filter(function (x) { return x && x.project_id; });
const reply = function (resp) { return [{ json: { response: resp } }]; };
const clean = function (s) { return String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); };
const digits = function (s) { return String(s || '').replace(/[^0-9]/g, ''); };
const thisYear = DateTime.fromISO(r.today).year;
const spokenDate = function (iso) { const d = DateTime.fromISO(String(iso || '')); if (!d.isValid) return ''; return d.year === thisYear ? d.toFormat('cccc, LLLL d') : d.toFormat('LLLL d, yyyy'); };
let matches = [];
if (r.phone.length === 10) matches = rows.filter(function (x) { return x.phone === r.phone && x.status === 'active'; });
if (!matches.length && r.project_id) {
  const byId = rows.filter(function (x) { return x.status === 'active' && (clean(x.project_id) === clean(r.project_id) || (digits(r.project_id).length >= 4 && digits(x.project_id) === digits(r.project_id))); });
  const words = r.name.toLowerCase().split(' ').filter(function (w) { return w.length > 2; });
  matches = byId.filter(function (x) { const n = String(x.customer_name).toLowerCase(); return words.some(function (w) { return n.indexOf(w) !== -1; }); });
  if (byId.length && !matches.length) return reply({ success: false, need: 'name', message: 'I found that project number. For privacy, what name is the project under?' });
}
